export function MissionCard(s,a){return`\n        <div class="isro-mission-card" data-index="${a}">\n            <div class="mission-card-header">\n                <span class="mission-status-badge ${s.status.toLowerCase().includes("success")?"success":s.status.toLowerCase().includes("partial")?"partial":s.status.toLowerCase().includes("planned")?"planned":s.status.toLowerCase().includes("operational")?"operational":"active"}">${s.status}</span>\n                <span class="mission-type-badge">${s.type}</span>\n            </div>\n            <h3 class="mission-name">${s.name}</h3>\n            <p class="mission-overview">${s.overview.substring(0,150)}...</p>\n            <div class="mission-quick-facts">\n                <div class="quick-fact">\n                    <span class="fact-label">Launch</span>\n                    <span class="fact-value">${s.launchDate.split(" ").slice(-2).join(" ")}</span>\n                </div>\n                <div class="quick-fact">\n                    <span class="fact-label">Vehicle</span>\n                    <span class="fact-value">${s.launchVehicle}</span>\n                </div>\n                <div class="quick-fact">\n                    <span class="fact-label">Cost</span>\n                    <span class="fact-value">${s.cost}</span>\n                </div>\n            </div>\n            <button class="mission-expand-btn" data-index="${a}" aria-expanded="false">\n                <span>Explore Mission</span>\n                <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="4 6 8 10 12 6"></polyline></svg>\n            </button>\n        </div>\n    `}export function MissionDetail(s){const a=s.objectives.map(s=>`<li>${s}</li>`).join(""),n=s.keyMilestones.map(s=>`<li>${s}</li>`).join(""),i=s.achievements.length>0?s.achievements.map(s=>`<li>${s}</li>`).join(""):"<li>To be updated after mission completion.</li>",t=s.facts.map(s=>`<p class="mission-fact">${s}</p>`).join("");return`\n        <div class="mission-detail-content">\n            <div class="mission-detail-grid">\n                <div class="detail-stat">\n                    <span class="detail-stat-label">Launch Date</span>\n                    <span class="detail-stat-value">${s.launchDate}</span>\n                </div>\n                <div class="detail-stat">\n                    <span class="detail-stat-label">Launch Vehicle</span>\n                    <span class="detail-stat-value">${s.launchVehicle}</span>\n                </div>\n                <div class="detail-stat">\n                    <span class="detail-stat-label">Mass</span>\n                    <span class="detail-stat-value">${s.mass}</span>\n                </div>\n                <div class="detail-stat">\n                    <span class="detail-stat-label">Cost</span>\n                    <span class="detail-stat-value">${s.cost}</span>\n                </div>\n            </div>\n            <div class="mission-detail-section">\n                <h4>Objectives</h4>\n                <ul>${a}</ul>\n            </div>\n            <div class="mission-detail-section">\n                <h4>Key Milestones</h4>\n                <ol class="milestones-list">${n}</ol>\n            </div>\n            <div class="mission-detail-section">\n                <h4>Achievements</h4>\n                <ul class="achievements-list">${i}</ul>\n            </div>\n            <div class="mission-detail-section">\n                <h4>Payload & Instruments</h4>\n                <p>${s.payload}</p>\n            </div>\n            <div class="mission-detail-section">\n                <h4>Interesting Facts</h4>\n                <div class="facts-container">${t}</div>\n            </div>\n        </div>\n    `}